  # --- Color mappings ---
  # Map brand.yml color palette to Bootstrap Sass variables
  if (!is.null(brand$color)) {
    foreground <- brand$color$foreground
    background <- brand$color$background
    primary    <- brand$color$primary
    secondary  <- brand$color$secondary

    if (!is.null(foreground)) {
      # brand foreground -> Bootstrap $body-color
      # This is the primary text color for the page
      vars$`body-color` <- foreground
    }

    if (!is.null(background)) {
      vars$`body-bg` <- background
    }

    if (!is.null(primary)) {
      vars$primary <- primary
    }

    if (!is.null(secondary)) {
      vars$secondary <- secondary
    }

    # Map named palette colors to Bootstrap theme colors
    palette <- brand$color$palette
    if (is.list(palette)) {
      theme_colors <- c("success", "info", "warning", "danger")
      for (tc in theme_colors) {
        if (!is.null(palette[[tc]])) {
          vars[[tc]] <- palette[[tc]]
        }
      }
    }
  }

  # --- Typography mappings ---
  if (!is.null(brand$typography)) {
    if (!is.null(brand$typography$base)) {
      vars$`font-family-base` <- brand$typography$base$family
      if (!is.null(brand$typography$base$size)) {
        vars$`font-size-base` <- brand$typography$base$size
      }
    }
    if (!is.null(brand$typography$headings)) {
      vars$`headings-font-family` <- brand$typography$headings$family
    }
  }

  # Build theme from mapped variables
  theme <- bs_theme(
    version = version,
    !!!vars
  }

  # Note: foreground doesn't map to a CSS custom property directly.
  # It flows through $body-color -> Bootstrap's Sass compilation,
  # but the generated CSS may not propagate to all text contexts
  # (e.g., .card-body, .nav-link default text color).
  # See https://github.com/rstudio/bslib/issues/1123

  theme
}

